import assert from "node:assert/strict";
import { test } from "node:test";
import { parseIsoDuration, parseYoutubeMeta, safeSegment } from "./parse";

test("parses auto-generated YouTube Music descriptions", () => {
  const meta = parseYoutubeMeta({
    title: "Blinding Lights",
    channelTitle: "The Weeknd - Topic",
    description:
      "Provided to YouTube by Universal Music Group\n\nBlinding Lights · The Weeknd\n\nAfter Hours\n\n℗ 2020 The Weeknd XO, Inc.\n\nReleased on: 2020-03-20\n\nAuto-generated by YouTube.",
  });
  assert.deepEqual(meta, { title: "Blinding Lights", artist: "The Weeknd", album: "After Hours", year: 2020 });
});

test("joins multiple artists", () => {
  const meta = parseYoutubeMeta({
    title: "x",
    channelTitle: "y",
    description: "Provided to YouTube by X\n\nSong · A · B\n\nAlbum\n\nReleased on: 2019-01-01",
  });
  assert.equal(meta.artist, "A, B");
});

test("falls back to Topic channel", () => {
  assert.deepEqual(parseYoutubeMeta({ title: "Song (Official Audio)", channelTitle: "Band - Topic" }), {
    title: "Song",
    artist: "Band",
    album: null,
    year: null,
  });
});

test("splits 'Artist - Title' and strips noise", () => {
  const meta = parseYoutubeMeta({ title: "Daft Punk - One More Time (Official Video)", channelTitle: "DaftPunkVEVO" });
  assert.equal(meta.artist, "Daft Punk");
  assert.equal(meta.title, "One More Time");
});

test("uses channel as artist when nothing else matches", () => {
  assert.equal(parseYoutubeMeta({ title: "Untitled", channelTitle: "SomeArtistVEVO" }).artist, "SomeArtist");
});

test("parses ISO durations", () => {
  assert.equal(parseIsoDuration("PT3M21S"), 201);
  assert.equal(parseIsoDuration("PT1H2M3S"), 3723);
  assert.equal(parseIsoDuration(null), null);
});

test("sanitises path segments", () => {
  assert.equal(safeSegment('AC/DC: "Live"?'), "AC_DC_ _Live__");
  assert.equal(safeSegment("..."), "_");
});
